from pathlib import Path

ROOT = Path('.')

def read(path):
    return (ROOT / path).read_text(encoding='utf-8')

def write(path, text):
    (ROOT / path).write_text(text, encoding='utf-8')

def replace_once(path, old, new):
    text = read(path)
    n = text.count(old)
    if n != 1:
        raise SystemExit(f'{path}: expected one match, found {n}: {old[:160]!r}')
    write(path, text.replace(old, new, 1))

# Version metadata.
replace_once('app/build.gradle.kts', '// Umnik v1.17.0', '// Umnik v1.17.1')
replace_once('app/build.gradle.kts', 'versionCode = 123\n        versionName = "1.17.0"', 'versionCode = 124\n        versionName = "1.17.1"')

# Changelog.
path = 'CHANGELOG.md'
text = read(path)
entry = '''## v1.17.1\n\n- Усилена работа обычных текстовых запросов в фоне: Umnik продолжает foreground-service при сворачивании приложения и показывает постоянное уведомление о текущей работе.\n- На Android 13+ добавлено штатное разрешение уведомлений; отказ от него не блокирует сам запрос, но скрывает обычное уведомление в шторке.\n- При обрыве сети после принятия запроса OpenRouter Umnik ждёт восстановления соединения, проверяет Generation ID и пытается получить уже готовый ответ без слепой повторной генерации.\n- Добавлен безопасный WorkManager-fallback после уничтожения процесса Android: восстанавливаются только прямые пользовательские текстовые запросы, для которых OpenRouter подтвердил response cache.\n- Recovery не сохраняет API-ключ: хранится только его SHA-256-отпечаток, а настоящий ключ повторно читается из зашифрованного SecretStore. Если ключ изменился, автоматический replay запрещается.\n- Перед повторным POST Umnik сначала пытается получить сохранённый результат через read-only generation/content; кешированный replay допускается только при подтверждённом cache HIT/MISS и ожидается как HIT.\n- Ручная кнопка «Стоп» окончательно отменяет запрос: recovery-запись и WorkManager-задача удаляются, а фоновый worker не может позже вернуть отменённый ответ.\n- Убрана служебная надпись «Другой чат отвечает · здесь можно отправить новый запрос» из поля ввода; параллельная работа остаётся видна по статусам чатов и системному уведомлению.\n- HTTP/2 оставлен включённым, ping-интервал возвращён к более спокойным 30 секундам; основная устойчивость теперь строится на восстановлении состояния, а не на удержании одного сокета любой ценой.\n- Версия: 1.17.1 / versionCode 124.\n\n'''
if text.startswith('## v1.17.1'):
    raise SystemExit('CHANGELOG already contains v1.17.1')
write(path, entry + text)

# README visible version.
replace_once('README.md', 'Текущая версия: **1.17.0**.', 'Текущая версия: **1.17.1**.')

# In-app guide: explain process-loss recovery accurately.
path = 'app/src/main/java/com/ayuemin/ymnik/help/UmnikUsageGuide.kt'
old = '''Если мобильное соединение HTTP/2 оборвалось уже после того, как OpenRouter принял запрос, Umnik не отправляет платный запрос вслепую второй раз. Когда OpenRouter успел завершить исходную генерацию и она доступна через кратковременный response cache, приложение проверяет её Generation ID и забирает тот же готовый ответ.\n\n**Пример:** отправьте длинную задачу, перейдите в браузер и вернитесь через несколько минут. Работа должна продолжаться, а состояние запроса останется видно.\n\nЕсли Android полностью уничтожил процесс приложения или OpenRouter не сохранил завершённую генерацию, Umnik сообщит, что запрос прерван, вместо скрытой повторной отправки и возможного двойного списания.'''
new = '''Если мобильное соединение оборвалось уже после того, как OpenRouter принял запрос, Umnik не отправляет платный запрос вслепую второй раз. Приложение ждёт сеть, проверяет Generation ID и при подтверждённом response cache пытается забрать тот же готовый ответ. Сначала используется read-only получение сохранённого результата, а точный повтор исходного запроса допускается только как безопасный cache replay.\n\nЕсли Android полностью уничтожил процесс приложения, Umnik может продолжить восстановление через системный WorkManager. Для этого сохраняются только служебные данные запроса и точный payload; API-ключ туда не записывается. Настоящий ключ заново читается из защищённого хранилища, а его отпечаток должен совпасть с исходным.\n\n**Пример:** отправьте длинную задачу, перейдите в браузер или погасите экран и вернитесь через несколько минут. Пока Android и OpenRouter позволяют продолжение, работа должна завершиться в исходном чате.\n\nЕсли OpenRouter не подтвердил безопасный cache, генерация недоступна или пользователь нажал «Стоп», Umnik не выполняет скрытый платный повтор и честно завершает восстановление.'''
replace_once(path, old, new)

# Privacy: recovery stores exact payload locally, never plaintext API key.
path = 'PRIVACY.md'
replace_once(path,
'- служебные записи фоновых Batch- и Video-задач;\n- диагностический журнал, если пользователь явно включил его запись.',
'- служебные записи фоновых Batch- и Video-задач;\n- временные записи восстановления обычных текстовых запросов: идентификаторы запроса/чата/сообщения, Generation ID, статус response cache, точный JSON-payload запроса и SHA-256-отпечаток использованного API-ключа; сам API-ключ в этих записях не хранится;\n- диагностический журнал, если пользователь явно включил его запись.')
marker = '## ◆ Оркестратор и передача между чатами\n'
section = '''## Фоновое восстановление запросов\n\nЕсли сетевое соединение или процесс Android прерываются после отправки обычного текстового запроса, Umnik может временно сохранить локальную recovery-запись, чтобы попытаться получить уже созданный ответ без слепой повторной генерации.\n\nТакая запись может содержать точный JSON-payload исходного запроса, поэтому в ней присутствует тот же текстовый контекст, который пользователь уже разрешил отправить OpenRouter. Запись хранится только во внутреннем каталоге приложения и удаляется после успешного восстановления, явной отмены или окончательной ошибки.\n\nAPI-ключ OpenRouter в recovery-запись не помещается. Вместо него сохраняется только SHA-256-отпечаток для проверки, что при восстановлении используется тот же ключ из зашифрованного SecretStore.\n\nАвтоматический replay разрешается только когда OpenRouter подтвердил участие исходного ответа в response cache. Если это не подтверждено, Umnik не делает скрытый повтор, чтобы снизить риск двойного списания.\n\n'''
text = read(path)
if section.strip() not in text:
    if marker not in text:
        raise SystemExit('PRIVACY marker not found')
    text = text.replace(marker, section + marker, 1)
write(path, text)

# Developer map and invariants.
path = 'docs/DEVELOPMENT.md'
replace_once(path,
'- `RequestKeepAliveService.kt` — foreground-служба Android, которая живёт до завершения последнего активного запроса.\n- `network/OpenRouterClient.kt` — сетевой вызов OpenRouter и отмена конкретного клиента.',
'- `RequestKeepAliveService.kt` — foreground-служба Android, которая живёт до завершения последнего активного запроса и показывает системное уведомление.\n- `OpenRouterRecoveryWorker.kt` — безопасное восстановление прямого текстового запроса после смерти процесса/долгого сетевого обрыва.\n- `network/OpenRouterRecoveryStore.kt` — временные локальные recovery-записи без plaintext API-ключа.\n- `network/OpenRouterRecoveryPolicy.kt` — правила, когда replay через response cache вообще разрешён.\n- `network/OpenRouterClient.kt` — сетевой вызов OpenRouter, Generation ID, response cache и отмена конкретного клиента.')
replace_once(path,
'12. Независимые действия Оркестратора можно запускать параллельно; действия, зависящие от предыдущего результата, остаются последовательными. Не возвращайте фиксированную группировку «по три».',
'12. Независимые действия Оркестратора можно запускать параллельно; действия, зависящие от предыдущего результата, остаются последовательными. Не возвращайте фиксированную группировку «по три».\n13. Сетевой обрыв после получения Generation ID не должен автоматически превращаться в новый платный запрос: сначала проверяется серверная генерация и подтверждение response cache.\n14. Recovery после смерти процесса разрешён только для прямого пользовательского текстового запроса; внутренние шаги Оркестратора не должны автономно дописываться worker-ом.\n15. Recovery не хранит plaintext API-ключ. Повтор допускается только при совпадении SHA-256-отпечатка текущего ключа с исходным.\n16. Ручной Stop окончателен: он удаляет recovery-запись, отменяет WorkManager и не позволяет фоновому worker позже доставить ответ.')

print('v1.17.1 release prep patch applied')
